{"implementation": "def solve(case):
    lines = case.get('lines', [])
    trajectory = []
    state = 'START'
    error_line = None
    for i, line in enumerate(lines):
        if ':' not in line:
            if error_line is None:
                error_line = i + 1
            trajectory.append({'content': line, 'type': 'unknown'})
        else:
            prefix, _, content = line.partition(':')
            prefix = prefix.strip()
            content = content.strip()
            if prefix == 'Thought':
                if state not in ('START', 'OBSERVATION'):
                    if error_line is None:
                        error_line = i + 1
                else:
                    state = 'THOUGHT'
                trajectory.append({'content': content, 'type': 'Thought'})
            elif prefix == 'Action':
                if state != 'THOUGHT':
                    if error_line is None:
                        error_line = i + 1
                else:
                    state = 'ACTION'
                trajectory.append({'content': content, 'type': 'Action'})
            elif prefix == 'Observation':
                if state != 'ACTION':
                    if error_line is None:
                        error_line = i + 1
                else:
                    state = 'OBSERVATION'
                trajectory.append({'content': content, 'type': 'Observation'})
            elif prefix == 'Final':
                if state != 'THOUGHT':
                    if error_line is None:
                        error_line = i + 1
                else:
                    state = 'FINAL'
                trajectory.append({'content': content, 'type': 'Final'})
            else:
                if error_line is None:
                    error_line = i + 1
                trajectory.append({'content': line, 'type': 'unknown'})
    valid = (error_line is None) and (state == 'FINAL')
    if not valid and error_line is None:
        if len(lines) == 0:
            error_line = 1
        else:
            error_line = len(lines)
    return {'valid': valid, 'error_line': error_line, 'trajectory': trajectory}"}
